import * as THREE from './vendor/three.module.js';
import {createLightField} from './light-fields.js?v=community38';
import {complexFootprints as f} from './complex-footprints.js?v=community38';
import {arenaCenter} from './arena-placement-v35.js?v=community38';
// Phone-sized light budget: ten nearby PBR sources plus instanced irradiance for distant lamps/cars.
// Ground spill is a soft approximation, not a ray-traced reflection of the LED texture.
export function createNightLighting(root,{salesOffice,terraces,towers,commercialLights,courtyard,publicRealm,neighborhood,traffic,arenaMedia,bridgeGlow,bridge,pavements=[]}){
 const group=new THREE.Group();group.name='Time-dependent architectural and street illumination';root.add(group);
 const warm=new THREE.Color(0xffdbab),head=new THREE.Color(0xffeed4),red=new THREE.Color(0xff3725),purple=new THREE.Color(0xb783ec);
 const gardenLamps=[...(salesOffice?.lamps??[]),...courtyard.lamps,...publicRealm.lamps,...(terraces?.lamps??[])];const street=createLightField(group,neighborhood.lamps.length),garden=createLightField(group,gardenLamps.length),beams=createLightField(group,traffic.cars.length*2,{beam:true}),brakes=createLightField(group,traffic.cars.length,{color:0xff3725}),arena=createLightField(group,12,{color:0x45cded}),accents=createLightField(group,courtyard.swings.length+courtyard.mediaColumns.length,{color:0xb783ec});
 neighborhood.lamps.forEach((p,i)=>street.set(i,p.x,-.34,p.z,8,8,0,warm,.65));street.commit();gardenLamps.forEach((p,i)=>garden.set(i,p.x+.4,p.y>4&&p.y<6?4.51:.065,p.z,p.y>4&&p.y<6?1.4:4.6,p.y>4&&p.y<6?1.4:4.6,0,warm,.75));garden.commit();
 const [ax,az]=arenaCenter;for(let i=0;i<12;i++){const a=i/12*Math.PI*2;arena.set(i,ax+Math.cos(a)*22,.07,az+Math.sin(a)*22,7,7,0,null,.55)}arena.commit();
 courtyard.swings.forEach((s,i)=>accents.set(i,s.point[0],.075,s.point[1],3.1,3.1,0,purple,.4));courtyard.mediaColumns.forEach((p,i)=>accents.set(i+courtyard.swings.length,p.x,.075,p.z,2.3,2.3,0,new THREE.Color(i%2?0xc383ef:0x65dce5),.35));accents.commit();
 const fanMat=new THREE.MeshStandardMaterial({color:0xffe5bf,emissive:0xffd59a,emissiveIntensity:0,roughness:.4});bridgeGlow.traverse(o=>{if(o.isMesh)o.material=fanMat});
 for(const boundary of f.fan.holes){const pts=boundary.slice(0,-1).map(([x,z])=>new THREE.Vector3(x,93.06,z));const mesh=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts,true,'centripetal'),Math.min(180,pts.length*3),.065,5,true),fanMat);bridgeGlow.add(mesh)}
 const fanSurface=bridge.material.clone();fanSurface.emissive.set(0xffce91);bridge.material=fanSurface;
 const lampLights=Array.from({length:4},()=>{const l=new THREE.PointLight(0xffddb1,0,24,2);group.add(l);return l});
 const arenaLights=Array.from({length:2},()=>{const l=new THREE.PointLight(0x46cbee,0,45,2);group.add(l);return l});
 const headLights=Array.from({length:4},()=>{const l=new THREE.SpotLight(0xffe8c0,0,32,.52,.65,2);group.add(l,l.target);return l});
 // Two pooled diffuse window sources: physical inverse-square falloff, no invented broad floodlighting.
 // Their intensity is illustrative, not measured luminaire data or full ray-traced interreflection.
 const windowLights=Array.from({length:2},()=>{const l=new THREE.PointLight(0xffd3a0,0,42,2);l.name='Subtle neighboring-window spill';group.add(l);return l});
 const facingBays=new Map();for(const [id,tower] of towers){const indices=new Set();for(let j=0;j<tower.columns;j++){const source=tower.windowSources[j];for(const [otherId,other] of towers){if(id===otherId)continue;for(const target of other.windowSources.slice(0,other.columns)){const dx=target.x-source.x,dz=target.z-source.z,d=Math.hypot(dx,dz);if(d>8&&d<32&&(dx*source.nx+dz*source.nz)/d>.72){indices.add(j);break}}if(indices.has(j))break}}facingBays.set(id,indices)}
 let nearWindows=[];
 const lastCamera=new THREE.Vector3(Infinity,Infinity,Infinity);let strength=0,wet=0,hour=21,lastChoice=-Infinity,nearLamps=[],nearCars=[];const point=new THREE.Vector3(),color=new THREE.Color();
 function setAtmosphere({elevation,hour:clock=21,weather='clear'}){strength=THREE.MathUtils.smoothstep(-elevation,-1,7);hour=clock;wet=weather==='rain'?1:weather==='snow'?.35:0;salesOffice?.setNight(strength);neighborhood.setNight(strength);traffic.setNight(strength);courtyard.setNight(strength);publicRealm?.setNight(strength);terraces?.setNight(strength);salesOffice?.setWetness(wet);neighborhood.setWetness(wet);courtyard.setWetness(wet);publicRealm?.setWetness(wet);for(const mat of pavements){mat.roughness=.91-wet*.49;mat.metalness=.02+wet*.12}fanMat.emissiveIntensity=strength*2.4;fanSurface.emissiveIntensity=strength*.055;for(const field of [street,garden,beams,brakes,arena,accents]){field.strength.value=strength;field.wetness.value=wet}}
 function update(t,camera=null){for(const tower of towers.values())tower.windowLights.update(t,hour,strength);commercialLights.update(t,hour,strength);street.mesh.visible=neighborhood.group.visible;beams.mesh.visible=brakes.mesh.visible=traffic.group.visible;
  const emission=arenaMedia.sampleEmission(t+.5);color.copy(emission.color);for(let i=0;i<12;i++){color.toArray(arena.tints,i*3);arena.powers[i]=.55*emission.power}arena.geometry.attributes.fieldTint.needsUpdate=true;arena.geometry.attributes.fieldPower.needsUpdate=true;
  for(const c of traffic.cars){const dx=Math.sin(c.heading),dz=Math.cos(c.heading),sx=Math.cos(c.heading),sz=-Math.sin(c.heading);for(let j=0;j<2;j++){const side=j?1:-1;beams.set(c.index*2+j,c.world.x+dx*(c.length/2+6.4)+sx*side*.57,-.345,c.world.z+dz*(c.length/2+6.4)+sz*side*.57,2.6,6.4,c.heading,head,.5)}brakes.set(c.index,c.world.x-dx*(c.length/2+1),-.343,c.world.z-dz*(c.length/2+1),1.9,2.8,c.heading,red,c.braking?.65:.09)}beams.commit();brakes.commit();for(const field of [street,garden,beams,brakes,arena,accents])field.clock.value=t;
  if(camera&&(Math.abs(t-lastChoice)>.4||lastCamera.distanceToSquared(camera.position)>4)){lastChoice=t;lastCamera.copy(camera.position);const candidates=[...gardenLamps,...(neighborhood.group.visible?neighborhood.lamps:[])];nearLamps=candidates.sort((a,b)=>point.set(a.x,a.y,a.z).distanceToSquared(camera.position)-point.set(b.x,b.y,b.z).distanceToSquared(camera.position)).slice(0,4);nearCars=traffic.group.visible?[...traffic.cars].sort((a,b)=>a.world.distanceToSquared(camera.position)-b.world.distanceToSquared(camera.position)).slice(0,2):[];
   const sources=[];for(const [id,tower] of towers)for(const source of tower.windowSources){if(!source.masked&&facingBays.get(id).has(source.index%tower.columns)&&tower.windowLights.strengths[source.index]>0){sources.push({...source,tower,distance:point.set(source.x,source.y,source.z).distanceToSquared(camera.position)})}}sources.sort((a,b)=>a.distance-b.distance);nearWindows=[];for(const s of sources){if(nearWindows.every(p=>Math.hypot(p.x-s.x,p.y-s.y,p.z-s.z)>6))nearWindows.push(s);if(nearWindows.length===2)break}
  }
  lampLights.forEach((l,i)=>{const p=nearLamps[i];l.intensity=p?strength*(p.y>5?190:65):0;if(p)l.position.set(p.x+.3,p.y-.15,p.z)});
  arenaLights.forEach((l,i)=>{const a=i===0?-.65:2.5;l.position.set(ax+Math.cos(a)*20.1,3.8,az+Math.sin(a)*20.1);l.color.copy(emission.color);l.intensity=strength*620*emission.power});
  headLights.forEach((l,i)=>{const c=nearCars[Math.floor(i/2)];l.intensity=c&&traffic.group.visible?strength*145:0;if(!c)return;const side=i%2?1:-1,dx=Math.sin(c.heading),dz=Math.cos(c.heading),sx=Math.cos(c.heading),sz=-Math.sin(c.heading);l.position.set(c.world.x+dx*c.length/2+sx*side*.57,.36,c.world.z+dz*c.length/2+sz*side*.57);l.target.position.set(l.position.x+dx*17,-.43,l.position.z+dz*17)});
  windowLights.forEach((light,i)=>{const source=nearWindows[i],glow=source?source.tower.windowLights.strengths[source.index]:0;light.intensity=strength*glow*100;if(source){light.position.set(source.x+source.nx*.15,source.y,source.z+source.nz*.15);light.color.fromArray(source.tower.windowLights.tints,source.index*3)}});
 }
 return{group,fields:{street,garden,beams,brakes,arena,accents},lampLights,arenaLights,headLights,windowLights,facingBays,setAtmosphere,update,get strength(){return strength},get wetness(){return wet},dispose(){for(const field of [street,garden,beams,brakes,arena,accents])field.dispose();root.remove(group);fanMat.dispose();fanSurface.dispose()}};
}
